PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `JurnalData` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `jurnal_id` INTEGER REFERENCES `Jurnals` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `nama` VARCHAR(255) NOT NULL, `no_hp` VARCHAR(255) NOT NULL, `tanggal` DATETIME NOT NULL, `tahun` INTEGER NOT NULL, `zis` VARCHAR(255) NOT NULL, `via` VARCHAR(255) NOT NULL, `sumber_dana` VARCHAR(255) NOT NULL, `nominal` FLOAT NOT NULL, `jenis_donatur` VARCHAR(255) NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `Jurnals` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `name` VARCHAR(255) NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, jenisJurnal TEXT);
CREATE TABLE IF NOT EXISTS "JurnalDataCleaning" (
    id INTEGER PRIMARY KEY,
    jurnal_id INTEGER,
    nama VARCHAR(255),
    no_hp VARCHAR(20),
    tanggal DATETIME,
    tahun INTEGER,
    zis VARCHAR(50),
    via VARCHAR(50),
    sumber_dana VARCHAR(100),
    nominal FLOAT,
    jenis_donatur VARCHAR(100),
    createdAt DATETIME,
    updatedAt DATETIME,
    FOREIGN KEY (jurnal_id) REFERENCES Jurnals(id)
);
CREATE TABLE `JurnalDataCleanings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `jurnal_id` INTEGER REFERENCES `Jurnals` (`id`), `nama` VARCHAR(255) NOT NULL, `no_hp` VARCHAR(255) NOT NULL, `tanggal` DATETIME NOT NULL, `tahun` INTEGER NOT NULL, `zis` VARCHAR(255) NOT NULL, `via` VARCHAR(255) NOT NULL, `sumber_dana` VARCHAR(255) NOT NULL, `nominal` FLOAT NOT NULL, `jenis_donatur` VARCHAR(255) NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
DELETE FROM sqlite_sequence;
COMMIT;
